def AdmittedSource.isInput (source : AdmittedSource) (t : source.source.table.declarations.Tensor) :
    Bool :=
  decide ((source.source.table.entry t).role = .input)

  | .sourceCompilation error =>
    s!"checked sourceCompilation: cause={repr error.cause}
warningAvailability={repr error.warnings}
mappings={repr error.mappings}"
  | .preparation error =>
    s!"checked preparation: cause={renderPreparationCause error.original.cause}
warnings={error.original.warnings.map toString}
mappings={repr error.mappings}"
  | .runtime error =>
    s!"checked runtime: cause={repr error.original.cause}
warnings={error.original.warnings.map toString}
mappings={repr error.mappings}"
